def parse_money(text):
    """' $1,234.50' -> 1234.5"""
    return float(text.strip().replace("$", "").replace(",", ""))


def line_revenue(quantity, unit_price, discount=0.0):
    """quantity x unit_price x (1 - discount), rounded to 2 decimals"""
    return round(quantity * unit_price * (1 - discount), 2)


def format_money(amount):
    """1234.5 -> '$1,234.50'"""
    return f"${amount:,.2f}"


print(parse_money(" $1,234.50"), line_revenue(2, 129.0, 0.15), format_money(1234.5))
